1	export type QuoteResult = {
2	  premium: number;
3	};
4	
5	export type ClaimResult = {
6	  payout: number;
7	  remainingCap: number;
8	};
9	
10	export type StepResult = QuoteResult | ClaimResult;
11	
12	export type ScenarioOutcome = {
13	  results: StepResult[];
14	};
15	
16	type Item = { type: string; cursed?: boolean; enchantment?: number };
17	
18	type Customer = { yearsWithMHPCO: number };
19	
20	/** The policy-scope context a quote is priced in: who is buying, and whether
21	 * this is their first contract or a follow-up. */
22	type Policy = { customer: Customer; isFollowUpContract: boolean };
23	
24	type Damage = { itemType: string; amount: number };
25	
26	type Incident = { cause: string; damages: Damage[] };
27	
28	type QuoteStep = { op: string; items: Item[] };
29	
30	type ClaimStep = { op: string; policy: number; incident: Incident };
31	
32	type Step = QuoteStep | ClaimStep;
33	
34	const isQuoteStep = (step: Step): step is QuoteStep => step.op === "quote";
35	
36	type Scenario = {
37	  customer: Customer;
38	  steps: Step[];
39	};
40	
41	const PROCESSING_FEE = 5;
42	const FIRST_INSURANCE_SURCHARGE = 0.1;
43	const CURSE_SURCHARGE = 0.5;
44	const HIGH_ENCHANTMENT_THRESHOLD = 5;
45	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
46	const LOYALTY_THRESHOLD_YEARS = 2;
47	const LOYALTY_DISCOUNT = 0.2;
48	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
49	
50	const BASE_PREMIUMS: Record<string, number> = {
51	  sword: 100,
52	  amulet: 60,
53	  staff: 80,
54	  potion: 40,
55	  rune: 25,
56	  moonstone: 25,
57	};
58	
59	const INSURANCE_VALUES: Record<string, number> = {
60	  sword: 1000,
61	  amulet: 600,
62	  rune: 250,
63	};
64	
65	const DEDUCTIBLE_PER_DAMAGE = 100;
66	const SEVERE_ENCHANTMENT_THRESHOLD = 8;
67	const SEVERE_ENCHANTMENT_REIMBURSEMENT = 0.5;
68	const FULL_REIMBURSEMENT = 1;
69	const CAP_MULTIPLIER = 2;
70	
71	const ALIKE_BLOCK_SIZE = 3;
72	const ALIKE_BLOCK_PREMIUM = 60;
73	
74	type AlikeGroup = [type: string, count: number];
75	
76	const groupAlikeItems = (items: Item[]): AlikeGroup[] => {
77	  const countByType = new Map<string, number>();
78	
79	  for (const item of items) {
80	    countByType.set(item.type, (countByType.get(item.type) ?? 0) + 1);
81	  }
82	
83	  return [...countByType];
84	};
85	
86	const basePremiumOfType = (type: string): number => BASE_PREMIUMS[type];
87	
88	const ownBasePremiumOf = (item: Item): number => basePremiumOfType(item.type);
89	
90	const basePremiumOfGroup = ([type, count]: AlikeGroup): number => {
91	  if (count === ALIKE_BLOCK_SIZE) return ALIKE_BLOCK_PREMIUM;
92	
93	  return count * basePremiumOfType(type);
94	};
95	
96	/**
97	 * The policy base premium: the sum of the item base premiums, with the
98	 * alike-block discount applied. Policy-scope modifiers are percentages OF
99	 * THIS amount — never of a total that already includes item surcharges.
100	 */
101	const policyBasePremiumOf = (items: Item[]): number =>
102	  groupAlikeItems(items)
103	    .map(basePremiumOfGroup)
104	    .reduce((total, groupPremium) => total + groupPremium, 0);
105	
106	/**
107	 * Item-scope surcharges: each is a percentage of the affected item's OWN base
108	 * premium, independent of the policy base and of the alike-block discount.
109	 */
110	const isCursed = (item: Item): boolean => item.cursed === true;
111	
112	const isHighlyEnchanted = (item: Item): boolean =>
113	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
114	
115	const itemSurchargeRateOf = (item: Item): number =>
116	  (isCursed(item) ? CURSE_SURCHARGE : 0) +
117	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE : 0);
118	
119	const itemSurchargesOf = (items: Item[]): number =>
120	  items.reduce(
121	    (total, item) => total + ownBasePremiumOf(item) * itemSurchargeRateOf(item),
122	    0,
123	  );
124	
125	/**
126	 * Policy-scope modifiers: each is a percentage of the policy base premium.
127	 * Surcharges and discounts are netted into a single rate, so the policy base is
128	 * multiplied exactly once — this keeps the result free of the rounding drift
129	 * that separate discount and surcharge terms would introduce. The netted rate
130	 * (and hence the returned amount) is negative when the discounts outweigh the
131	 * surcharges.
132	 */
133	const isLongStanding = (customer: Customer): boolean =>
134	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
135	
136	const policyModifierRateOf = ({ customer, isFollowUpContract }: Policy): number =>
137	  FIRST_INSURANCE_SURCHARGE -
138	  (isLongStanding(customer) ? LOYALTY_DISCOUNT : 0) -
139	  (isFollowUpContract ? FOLLOW_UP_CONTRACT_DISCOUNT : 0);
140	
141	const policyModifiersOn = (policyBase: number, policy: Policy): number =>
142	  policyBase * policyModifierRateOf(policy);
143	
144	const quotePremium = (items: Item[], policy: Policy): number => {
145	  const policyBase = policyBasePremiumOf(items);
146	  const premium =
147	    policyBase +
148	    itemSurchargesOf(items) +
149	    policyModifiersOn(policyBase, policy) +
150	    PROCESSING_FEE;
151	
152	  return Math.ceil(premium);
153	};
154	
155	/**
156	 * Whether any step precedes this one. A quote is a follow-up contract when the
157	 * customer already holds one, and today every step is a quote — so "has a
158	 * predecessor" and "is a follow-up contract" coincide.
159	 *
160	 * They stop coinciding once claim steps exist: a claim at index 0 would make
161	 * the quote at index 1 look like a follow-up. At that point the caller must
162	 * count preceding QUOTE steps instead of asking this. The name is deliberately
163	 * about position, not contracts, so that the substitution is a visible change
164	 * at the call site rather than a silent redefinition here.
165	 */
166	const hasPrecedingStep = (stepIndex: number): boolean => stepIndex > 0;
167	
168	const insuranceSumOf = (items: Item[]): number =>
169	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
170	
171	const isSeverelyEnchanted = (item: Item): boolean =>
172	  (item.enchantment ?? 0) >= SEVERE_ENCHANTMENT_THRESHOLD;
173	
174	const reimbursementRateFor = (item: Item): number =>
175	  isSeverelyEnchanted(item) ? SEVERE_ENCHANTMENT_REIMBURSEMENT : FULL_REIMBURSEMENT;
176	
177	const payoutForDamage = (damage: Damage, items: Item[]): number => {
178	  const item = items.find(({ type }) => type === damage.itemType) as Item;
179	
180	  return damage.amount * reimbursementRateFor(item) - DEDUCTIBLE_PER_DAMAGE;
181	};
182	
183	/**
184	 * The quote step a claim is filed against. Today this ASSUMES the referenced
185	 * index holds a quote: nothing has forced the assumption to be checked yet, and
186	 * a claim naming a non-quote step fails here with an opaque undefined-property
187	 * error rather than a rejection.
188	 *
189	 * The assumption is isolated in this function on purpose. The pending
190	 * error-handling tests ("a claim for an item not part of the policy", "a claim
191	 * with a damage entry of an unknown item type") are what will force a real
192	 * rejection, and this is the single place that has to change when they do.
193	 */
194	const policyReferencedBy = (claim: ClaimStep, steps: Step[]): QuoteStep =>
195	  steps[claim.policy] as QuoteStep;
196	
197	const settleClaim = (claim: ClaimStep, steps: Step[]): ClaimResult => {
198	  const policy = policyReferencedBy(claim, steps);
199	  const cap = CAP_MULTIPLIER * insuranceSumOf(policy.items);
200	  const payout = claim.incident.damages.reduce(
201	    (total, damage) => total + payoutForDamage(damage, policy.items),
202	    0,
203	  );
204	
205	  return { payout, remainingCap: cap - payout };
206	};
207	
208	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
209	  results: scenario.steps.map((step, stepIndex) =>
210	    isQuoteStep(step)
211	      ? {
212	          premium: quotePremium(step.items, {
213	            customer: scenario.customer,
214	            isFollowUpContract: hasPrecedingStep(stepIndex),
215	          }),
216	        }
217	      : settleClaim(step, scenario.steps),
218	  ),
219	});
